const assert = require('node:assert/strict');
const { execFileSync } = require('node:child_process');
const { readFileSync } = require('node:fs');
const { chromium } = require('playwright');

const psql = (query) => execFileSync('docker', [
  'exec', 'glo35-ui-verification-db', 'psql', '-v', 'ON_ERROR_STOP=1',
  '-U', 'app', '-d', 'frames', '-Atc', query,
], { encoding: 'utf8' }).trim();
const token = readFileSync('/private/tmp/glo35-operator.Ac2e92','utf8').trim();
const original = 'e60610e9-23ac-4b17-9ebf-eb9faddb4069';
psql(`
  INSERT INTO import_jobs (job_id, owner_id, import_mode, force_overwrite, status, object_bucket,
    object_key, object_version_id, upload_expires_at, dispatch_until, finished_at)
  VALUES ('${original}', 'local-import-operator','DELTA',false,'COMPLETED','test',
    'uploads/${original}/inventory_frame.csv','version',now()-interval '8 days',
    now()-interval '8 days',now()-interval '8 days') ON CONFLICT DO NOTHING;
  INSERT INTO frame(frame_id) SELECT 'SMOKE-' || lpad(i::text, 2,'0') FROM generate_series(1,26) i ON CONFLICT DO NOTHING;
  INSERT INTO frame_version(frame_id, status, valid_from, import_job_id)
    SELECT frame_id, 'LIVE', now(), CASE WHEN frame_id='SMOKE-01' THEN '${original}'::uuid END FROM frame f WHERE NOT EXISTS (SELECT 1 FROM frame_version v WHERE v.frame_id=f.frame_id);
`);

(async () => {
  const browser = await chromium.launch({ headless: true, channel: 'chrome' });
  try {
    const page = await browser.newPage({ viewport: { width: 1366, height: 900 } });
    await page.goto('http://127.0.0.1:13035');
    await page.getByRole('button', { name: 'View history for SMOKE-01' }).waitFor();
    await page.getByRole('button', { name: 'Next', exact: true }).click();
    await page.getByRole('button', { name: 'View history for SMOKE-26' }).waitFor();
    await page.getByRole('button', { name: 'Previous' }).click();
    await page.getByRole('button', { name: 'View history for SMOKE-01' }).click();
    await page.getByRole('dialog', { name: 'Version history' }).waitFor();
    await page.getByRole('button', { name: 'Import job ' + original }).click();
    await page.getByText('Enter your local operator token to view this job.').waitFor();
    await page.getByLabel('Local operator token').fill(token);
    await page.getByText('Completed', { exact: true }).waitFor();
    await page.getByRole('button', { name: 'View row errors' }).click();
    await page.getByText('No row errors are available.', { exact: false }).waitFor();

    await page.getByLabel('Inventory CSV').setInputFiles({
      name: 'inventory_frame.csv', mimeType: 'text/csv', buffer: Buffer.from('frame_id\nSMOKE-01\n'),
    });
    await page.getByLabel('Force overwrite', { exact: true }).check();
    await page.getByRole('button', { name: 'Upload CSV' }).click();
    await page.getByText('Confirm the forced overwrite before uploading.').waitFor();
    await page.getByLabel('I understand this can replace newer edits and restore manually deleted frames.').check();
    const put = page.waitForResponse((response) => response.request().method() === 'PUT');
    await page.getByRole('button', { name: 'Upload CSV' }).click();
    const upload = await put;
    assert.equal(upload.status(), 200);
    assert.equal(await page.getByLabel('Force overwrite', { exact: true }).isChecked(), false);
    const objectVersion = (await upload.allHeaders())['x-amz-version-id'];
    assert.ok(objectVersion);
    const job = await page.locator('.job-id').textContent();
    assert.match(job, /^[0-9a-f-]{36}$/);
    assert.notEqual(job, original);
    assert.equal(psql(`SELECT force_overwrite FROM import_jobs WHERE job_id='${job}'`), 't');

    // The worker lands separately. Provide its eventual result to verify the UI's polling and paging.
    psql(`
      UPDATE import_jobs SET object_version_id='${objectVersion}', status='COMPLETED_WITH_ERRORS',
        rows_read=26, rows_rejected=26, finished_at=clock_timestamp() WHERE job_id='${job}';
      INSERT INTO import_row_errors(job_id,row_number,code,frame_id,detail)
        SELECT '${job}', i, 'INVALID_FIELD','SMOKE-01', 'Invalid test row ' || i FROM generate_series(1,26) i ON CONFLICT DO NOTHING;
    `);
    await page.getByText('Completed with errors', { exact: true }).waitFor();
    await page.getByRole('button', { name: 'View row errors' }).click();
    await page.getByText('Invalid test row 25', { exact: true }).waitFor();
    await page.getByRole('button', { name: 'Next', exact: true }).click();
    await page.getByText('Invalid test row 26', { exact: true }).waitFor();
    await page.screenshot({ path: '/private/tmp/glo35-browser-test/imports.png' });
    await page.setViewportSize({ width: 360, height: 800 });
    assert.equal(await page.evaluate(() => document.documentElement.scrollWidth), 360);
    console.log('Verified browser inventory paging, durable history link, forced upload confirmation, signed PUT, job polling and paginated row errors');
  } finally {
    await browser.close();
  }
})().catch((error) => { console.error(error); process.exitCode = 1; });
