    ...job,
    mode: job.mode as ImportMode,
    status: job.status as ImportJobStatus,
    createdAt: timestamp(job.createdAt),
    uploadExpiresAt: timestamp(job.uploadExpiresAt),
    finishedAt: job.finishedAt ? timestamp(job.finishedAt) : null,
  }
}

